import {COMPARE_EDGE} from './compare-core.mjs?v=20261027-replace2';

export function installCompare(api){
  const {$}=api;
  $('a4-output').insertAdjacentHTML('afterend','<button id="compare-open" class="secondary full">比對兩份 PDF</button>');
  document.body.insertAdjacentHTML('beforeend',`<dialog id="compare-dialog" class="work-dialog compare-dialog" aria-labelledby="compare-title">
    <div class="preview-header"><div><h2 id="compare-title">兩份 PDF 差異比對</h2><p>選擇已加入的兩份來源，依原始頁序比對畫面；不套用工作區的裁切與標記。</p></div><button id="compare-close" class="secondary">關閉</button></div>
    <div class="compare-options"><label>原稿 A<select id="compare-a"></select></label><label>新版 B<select id="compare-b"></select></label><label>差異容差<select id="compare-threshold"><option value="12">敏感（12）</option><option value="28" selected>一般（28）</option><option value="60">忽略較小色差（60）</option></select></label></div>
    <div class="compare-navigation"><button id="compare-prev" class="secondary">上一頁</button><label>頁碼<input id="compare-page" type="number" min="1" value="1"></label><span id="compare-count"></span><button id="compare-next" class="secondary">下一頁</button><button id="compare-scan" class="secondary">掃描全部頁面</button><button id="compare-cancel" class="secondary" hidden>停止比對</button><button id="compare-download" class="secondary" disabled>下載此頁差異圖</button></div>
    <p id="compare-status" class="status" role="status"></p><div class="compare-papers"><figure><figcaption id="compare-label-a">原稿 A</figcaption><img id="compare-image-a" alt="原稿 A 的頁面"></figure><figure><figcaption id="compare-label-b">新版 B</figcaption><img id="compare-image-b" alt="新版 B 的頁面"></figure><figure><figcaption>差異位置（紅色）</figcaption><img id="compare-image-diff" alt="兩頁的影像差異"></figure></div><div id="compare-results" class="compare-results"></div>
    <p class="field-hint">每次只處理一對頁面，預覽長邊最多 1,200 px。標示為影像色差，包含位置、字型或掃描偏移，不等於逐字審稿；極小字或細節可能不明顯。文件留在這台裝置。</p>
  </dialog>`);
  const dialog=$('compare-dialog'),stats=new Map();let sources=[],current=0,serial=0,controller,queue=Promise.resolve(),loading=false,urls=[],difference=null;
  const say=(text,error=false)=>{$('compare-status').textContent=text;$('compare-status').classList.toggle('error',error);};
  const pair=()=>[$('compare-a').value,$('compare-b').value].map(id=>sources.find(source=>source.id===id));
  const count=()=>Math.max(...pair().map(source=>source?.count||0));
  function controls(){for(const id of ['compare-a','compare-b','compare-threshold','compare-page','compare-scan'])$(id).disabled=loading;$('compare-prev').disabled=loading||current<=0;$('compare-next').disabled=loading||current>=count()-1;$('compare-cancel').hidden=!loading;$('compare-download').disabled=loading||!difference;$('compare-page').max=String(count());$('compare-page').value=String(current+1);$('compare-count').textContent=`/ ${count()} 頁`;}
  function clearImages(){for(const url of urls)URL.revokeObjectURL(url);urls=[];difference=null;for(const name of ['a','b','diff'])$('compare-image-'+name).removeAttribute('src');}
  function results(){const fragment=document.createDocumentFragment();for(const [index,result]of [...stats].sort((a,b)=>a[0]-b[0])){const button=document.createElement('button');button.className='secondary';button.textContent=`第 ${index+1} 頁：${result.missing?'其中一份缺頁':result.changed?`畫面差異 ${(result.changed/result.total*100).toFixed(2)}%`:'未發現畫面差異'}`;button.onclick=()=>{if(!loading){current=index;void show();}};fragment.append(button);}$('compare-results').replaceChildren(fragment);}
  function workerDiff(a,b,width,height,signal){return new Promise((resolve,reject)=>{const worker=new Worker(new URL('./compare-worker.mjs?v=20261027-replace2',import.meta.url),{type:'module'});const finish=(error,value)=>{signal.removeEventListener('abort',abort);worker.terminate();error?reject(error):resolve(value);};const abort=()=>finish(signal.reason);signal.addEventListener('abort',abort,{once:true});worker.onmessage=({data})=>finish(data.error?Error(data.error):null,data);worker.onerror=()=>finish(Error('影像比對未能完成，請重試。'));if(signal.aborted){abort();return;}worker.postMessage({a:a.buffer,b:b.buffer,width,height,threshold:Number($('compare-threshold').value)},[a.buffer,b.buffer]);});}
  const blob=canvas=>new Promise((resolve,reject)=>canvas.toBlob(value=>value?resolve(value):reject(Error('無法建立差異圖。')),'image/png'));
  async function compare(index,signal,visual){
    const documents=pair(),bitmaps=[],canvases=[];
    try{
      for(const source of documents){signal.throwIfAborted();if(index>=source.count){bitmaps.push(null);continue;}const rendered=await api.renderBlob(source,index,144,'png',false,{}, {maxEdge:COMPARE_EDGE});signal.throwIfAborted();bitmaps.push(await createImageBitmap(rendered.blob));}
      signal.throwIfAborted();const width=Math.max(1,...bitmaps.map(b=>b?.width||0)),height=Math.max(1,...bitmaps.map(b=>b?.height||0)),pixels=[],pictures=[];
      for(const bitmap of bitmaps){const canvas=document.createElement('canvas');canvases.push(canvas);canvas.width=width;canvas.height=height;const context=canvas.getContext('2d',{willReadFrequently:true});context.fillStyle='#fff';context.fillRect(0,0,width,height);if(bitmap)context.drawImage(bitmap,0,0);pixels.push(context.getImageData(0,0,width,height).data);if(visual)pictures.push(await blob(canvas));}
      const result=await workerDiff(...pixels,width,height,signal);signal.throwIfAborted();
      if(visual){const canvas=canvases[0];canvas.getContext('2d').putImageData(new ImageData(result.overlay,width,height),0,0);pictures.push(await blob(canvas));}
      return {changed:result.changed,total:result.total,missing:bitmaps.some(b=>!b),pictures};
    }finally{for(const bitmap of bitmaps)bitmap?.close();for(const canvas of canvases)canvas.width=canvas.height=0;}
  }
  function enqueue(action){controller?.abort();api.cancelRendering();controller=new AbortController();const signal=controller.signal,version=++serial;loading=true;controls();queue=queue.catch(()=>{}).then(async()=>{try{signal.throwIfAborted();if(!dialog.open)return;await action(signal,version);}catch(error){if(version===serial&&dialog.open)say(signal.aborted?'已停止比對，已完成的結果仍保留。':error.message,!signal.aborted);}finally{if(version===serial){loading=false;controls();}}});return queue;}
  function show(){clearImages();return enqueue(async(signal,version)=>{say(`正在比對第 ${current+1} 頁…`);const result=await compare(current,signal,true);if(signal.aborted||version!==serial||!dialog.open)return;clearImages();difference=result.pictures[2];['a','b','diff'].forEach((name,index)=>{$('compare-image-'+name).src=urls[index]=URL.createObjectURL(result.pictures[index]);});stats.set(current,{changed:result.changed,total:result.total,missing:result.missing});results();const documents=pair();for(const [index,name]of ['a','b'].entries())$('compare-label-'+name).textContent=`${index?'B':'A'} · ${documents[index].name}${current>=documents[index].count?'（此頁不存在）':''}`;say(result.missing?'這一頁只存在於其中一份文件。':result.changed?`第 ${current+1} 頁：畫面差異 ${(result.changed/result.total*100).toFixed(2)}%，紅色為差異位置。`:`第 ${current+1} 頁：未發現畫面差異。`);});}
  for(const id of ['compare-a','compare-b','compare-threshold'])$(id).onchange=()=>{current=0;stats.clear();results();clearImages();void show();};
  $('compare-prev').onclick=()=>{current--;void show();};$('compare-next').onclick=()=>{current++;void show();};
  $('compare-page').onchange=()=>{const value=Number($('compare-page').value);if(!Number.isInteger(value)||value<1||value>count()){say('請輸入有效頁碼。',true);controls();return;}current=value-1;void show();};
  $('compare-scan').onclick=()=>enqueue(async(signal)=>{for(let index=0;index<count();index++){signal.throwIfAborted();say(`正在比對 ${index+1} / ${count()} 頁…`);const result=await compare(index,signal,false);stats.set(index,{changed:result.changed,total:result.total,missing:result.missing});results();await new Promise(resolve=>setTimeout(resolve,0));}say(`已完成 ${stats.size} 頁，${[...stats.values()].filter(result=>result.changed||result.missing).length} 頁有畫面差異或缺頁。`);});
  $('compare-cancel').onclick=()=>{controller?.abort();api.cancelRendering();};
  $('compare-download').onclick=()=>{if(difference&&!loading)api.download(difference,`${api.filename()}_差異_p${String(current+1).padStart(3,'0')}.png`);};
  $('compare-close').onclick=()=>dialog.close();dialog.addEventListener('close',()=>{serial++;controller?.abort();api.cancelRendering();clearImages();stats.clear();results();loading=false;void queue.finally(()=>{if(!dialog.open){sources=[];api.setBusy(false);}});});
  $('compare-open').onclick=()=>{if(api.isBusy())return;const candidates=[...api.getSources().values()];if(candidates.length<2){api.status('請先加入兩份要比對的 PDF，再開啟差異比對。');return;}sources=candidates;api.setBusy(true);for(const id of ['compare-a','compare-b']){$(id).replaceChildren(...sources.map(source=>new Option(`${source.name} · ${source.count} 頁`,source.id)));}$('compare-b').value=sources[1].id;current=0;stats.clear();results();dialog.showModal();void show();};
  return {refresh(){$('compare-open').disabled=api.isBusy();}};
}
